// <autogenerated />
using Microsoft.AspNetCore.Components;
using Shared.DTO.Departments;
using Shared.DTO.WorkOrder;
using System.Net.Http.Json;
using static System.Net.WebRequestMethods;

namespace HandymanWorkshop.Client.Pages.WorkOrder
{
    public partial class Details
    {

        [Parameter]
        public string id { get; set; }

        WorkOrderDto workOrder { get; set; } = new WorkOrderDto();

        [Inject]
        protected NavigationManager? NavMan { get; set; }

        protected decimal price { get; set; } = 0;

        protected async override Task OnInitializedAsync()
        {
            workOrder = await Http.GetFromJsonAsync<WorkOrderDto>("api/WorkOrders/" + id);

            price = workOrder.HourlyRate * workOrder.EstimatedHours;
        }
    }
}
